const menuButton=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');
if(menuButton){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.textContent=open?'Close':'Menu';nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.textContent='Menu';menuButton.focus()}})}
document.querySelectorAll('[data-service-tabs]').forEach(group=>{const buttons=[...group.querySelectorAll('[data-filter]')];const scope=group.closest('[data-services]');buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));const selected=button.dataset.filter;scope.querySelectorAll('[data-service-category]').forEach(card=>{card.hidden=selected!=='all'&&card.dataset.serviceCategory!==selected});const count=scope.querySelector('[data-filter-count]');if(count)count.textContent=selected==='all'?'All treatment categories':button.textContent.trim()+' treatments';}));});
const interest=document.querySelector('#booking-interest');if(interest){const result=document.querySelector('#booking-result'),link=document.querySelector('#treatment-choice');interest.addEventListener('change',()=>{const option=interest.selectedOptions[0];result.hidden=!interest.value;if(interest.value){link.href=interest.value;link.textContent='Explore '+option.textContent.toLowerCase()+' →';document.querySelector('#booking-summary').textContent='Start with the treatment information, then use the official booking website to check current prices and appointment times. Your selection stays in this browser.'}})}
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('pending');observer.unobserve(entry.target)}})},{threshold:.07});document.querySelectorAll('.reveal').forEach(el=>{if(el.getBoundingClientRect().top>innerHeight){el.classList.add('pending');observer.observe(el)}})}
// Optional, lightweight pointer motion. The native cursor stays visible.
if(matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)').matches){
 const halo=document.createElement('div');halo.className='cursor-halo';halo.setAttribute('aria-hidden','true');document.body.append(halo);let x=-100,y=-100,scheduled=false;
 document.addEventListener('pointermove',e=>{x=e.clientX;y=e.clientY;if(!scheduled){scheduled=true;requestAnimationFrame(()=>{halo.style.transform=`translate(${x-14}px,${y-14}px)`;halo.style.opacity='1';scheduled=false})}halo.classList.toggle('on-link',Boolean(e.target.closest('a,button,summary,select')));},{passive:true});
 document.addEventListener('pointerleave',()=>{halo.style.opacity='0'});
 document.querySelectorAll('.button').forEach(b=>{b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.035}px,${(e.clientY-r.top-r.height/2)*.06}px)`});b.addEventListener('pointerleave',()=>{b.style.transform=''})});
 document.querySelectorAll('.hero-media').forEach(area=>{const img=area.querySelector('img');area.addEventListener('pointermove',e=>{const r=area.getBoundingClientRect();img.style.transform=`scale(1.025) translate(${(e.clientX-r.left-r.width/2)*.007}px,${(e.clientY-r.top-r.height/2)*.007}px)`});area.addEventListener('pointerleave',()=>{img.style.transform=''})});
}
